action.code:
if (hash < 0.0f || hash > 1.0f) {
    LOG(FATAL) << "Hash value out of range: " << hash;
}
if (partition_to_bucket.empty()) {
    LOG(FATAL) << "Partition map is empty";
}
auto it = partition_to_bucket.upper_bound(hash);
if (it == partition_to_bucket.end()) {
    return partition_to_bucket.begin()->second;
}
return it->second;

